import json,glob,collections,sys
recs={}
by_type=collections.defaultdict(list)
for f in glob.glob('/tmp/export/*.ndjson'):
    for line in open(f):
        r=json.loads(line)
        recs[r['id']]=r
        by_type[r['resourceType']].append(r)
def ext(r,u,*keys):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+u):
            for k in ('valueString','valueDateTime','valueDate','valueCode'):
                if k in e: return e[k]
    return None
def et(r): return ext(r,'event-time') or ''
pat_of={}
for t,rs in by_type.items():
    for r in rs:
        s=r.get('subject') or r.get('patient') or r.get('for')
        if s: pat_of[r['id']]=s['reference'].split('/')[1]
acc_by=collections.defaultdict(list)
for b in by_type['Basic']:
    acc_by[ext(b,'accession')].append(b)
spec_by_id={s['id']:s for s in by_type['Specimen']}
patients={p['id']:p for p in by_type['Patient']}
eps=collections.defaultdict(list)
for e in by_type['EpisodeOfCare']: eps[e['patient']['reference'].split('/')[1]].append(e)

def render(pid):
    out=[]
    p=patients[pid]
    mrn=p['identifier'][0]['value']
    out.append(f"### {pid} {p['name'][0]['text']} | MRN {mrn} | DOB {p['birthDate']} | {p['gender']}")
    for e in eps[pid]:
        out.append(f"  EPISODE {e['id']} dx {e['period']['start']} {e['type'][0]['text']} status={e['status']}")
    rs=[r for r in recs.values() if pat_of.get(r['id'])==pid]
    rs.sort(key=lambda r:(et(r),r['id']))
    for r in rs:
        t=r['resourceType']; i=r['id']; e=et(r)
        if t in ('Patient','EpisodeOfCare'): continue
        if t=='Condition':
            out.append(f"  [{e}] Condition {i}: {r['code']['text']} | recorder {r.get('recorder',{}).get('display')} recordedDate={r.get('recordedDate')}")
        elif t=='AllergyIntolerance':
            out.append(f"  [{e}] Allergy {i}: {r['code']['text']} | {[m['text'] for rx in r.get('reaction',[]) for m in rx['manifestation']]}")
        elif t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            acc=r.get('identifier',[{}])[0].get('value')
            notes=' | notes: '+'; '.join(n['text'] for n in r.get('note',[])) if r.get('note') else ''
            out.append(f"  [{e}] Obs {i}: {r['code']['text']} status={r['status']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} value={r.get('valueString')} acc={acc} spec={sp}{notes}")
            if sp and sp in spec_by_id:
                s=spec_by_id[sp]
                out.append(f"        Spec {sp}: acc={s.get('accessionIdentifier',{}).get('value')} coll={s.get('collection',{}).get('collectedDateTime')} by {s.get('collection',{}).get('collector',{}).get('display')} label: {ext(s,'label-name')} / MRN {ext(s,'label-mrn')} / DOB {ext(s,'label-dob')} subj={pat_of.get(sp)}")
            for b in acc_by.get(acc,[]):
                out.append(f"        Acc {b['id']}: acc={ext(b,'accession')} {ext(b,'patient-name')} / MRN {ext(b,'patient-mrn')} / DOB {ext(b,'patient-dob')} recv={ext(b,'received')} by {b.get('author',{}).get('display')}")
        elif t=='Specimen':
            pass
        elif t=='MedicationAdministration':
            notes=' | '+'; '.join(n['text'] for n in r.get('note',[])) if r.get('note') else ''
            out.append(f"  [{e}] MedAdmin {i}: {r['medicationCodeableConcept']['text']} {r.get('dosage',{}).get('text')} status={r['status']} by {r.get('performer',[{}])[0].get('actor',{}).get('display')}{notes}")
        elif t=='MedicationDispense':
            notes=' | '+'; '.join(n['text'] for n in r.get('note',[])) if r.get('note') else ''
            out.append(f"  [{e}] MedDisp {i}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver')} sig={[d['text'] for d in r.get('dosageInstruction',[])]} status={r['status']}{notes}")
        elif t=='DocumentReference':
            out.append(f"  [{e}] Doc {i}: type={r['type']['text']} author={r.get('author',[{}])[0].get('display')} role={ext(r,'author-role')} status={r.get('docStatus')}")
            for ln in r['description'].split('\n'):
                if ln.strip(): out.append('        | '+ln.strip())
        elif t=='Task':
            if r['status']=='requested':
                out.append(f"  [{r.get('authoredOn')}] REQUEST {i}: {r['code']['coding'][0]['code']} focus={r['focus']['reference']} :: {r['description']}")
            else:
                out.append(f"  ITEM {i}: {r.get('businessStatus')}")
        else:
            out.append(f"  [{e}] {t} {i}")
    # orphan specimens whose subject is pid but no obs rendered
    return '\n'.join(out)
if __name__=='__main__':
    ids=sorted(patients)
    if len(sys.argv)>1:
        a=int(sys.argv[1]); b=int(sys.argv[2]); ids=ids[a:b]
    for pid in ids:
        print(render(pid)); print()
EOF
